1	import { TRPCError } from '../error/TRPCError';
2	import { Simplify } from '../types';
3	import { AnyRootConfig, RootConfig } from './internals/config';
4	import { ParseFn } from './internals/getParseFn';
5	import { ProcedureBuilderMiddleware } from './internals/procedureBuilder';
6	import {
7	  DefaultValue as FallbackValue,
8	  MiddlewareMarker,
9	  Overwrite,
10	} from './internals/utils';
11	import { ProcedureParams } from './procedure';
12	import { ProcedureType } from './types';
13	
14	/**
15	 * @internal
16	 */
17	interface MiddlewareResultBase {
18	  /**
19	   * All middlewares should pass through their `next()`'s output.
20	   * Requiring this marker makes sure that can't be forgotten at compile-time.
21	   */
22	  readonly marker: MiddlewareMarker;
23	}
24	
25	/**
26	 * @internal
27	 */
28	interface MiddlewareOKResult<_TParams extends ProcedureParams>
29	  extends MiddlewareResultBase {
30	  ok: true;
31	  data: unknown;
32	  // this could be extended with `input`/`rawInput` later
33	}
34	
35	/**
36	 * @internal
37	 */
38	interface MiddlewareErrorResult<_TParams extends ProcedureParams>
39	  extends MiddlewareResultBase {
40	  ok: false;
41	  error: TRPCError;
42	}
43	
44	/**
45	 * @internal
46	 */
47	export type MiddlewareResult<TParams extends ProcedureParams> =
48	  | MiddlewareErrorResult<TParams>
49	  | MiddlewareOKResult<TParams>;
50	
51	/**
52	 * @internal
53	 */
54	export interface MiddlewareBuilder<
55	  TRoot extends ProcedureParams,
56	  TNewParams extends ProcedureParams,
57	> {
58	  /**
59	   * Create a new builder based on the current middleware builder
60	   */
61	  unstable_pipe<$Params extends ProcedureParams>(
62	    fn: {
63	      _config: TRoot['_config'];
64	      _meta: TRoot['_meta'];
65	      _ctx_out: Overwrite<TRoot['_ctx_out'], TNewParams['_ctx_out']>;
66	      _input_in: FallbackValue<TRoot['_input_in'], TNewParams['_input_in']>;
67	      _input_out: FallbackValue<TRoot['_input_out'], TNewParams['_input_out']>;
68	      _output_in: FallbackValue<TRoot['_output_in'], TNewParams['_output_in']>;
69	      _output_out: FallbackValue<
70	        TRoot['_output_out'],
71	        TNewParams['_output_out']
72	      >;
73	    } extends infer OParams extends ProcedureParams
74	      ?
75	          | MiddlewareBuilder<OParams, $Params>
76	          | MiddlewareFunction<OParams, $Params>
77	      : never,
78	  ): CreateMiddlewareReturnInput<
79	    TRoot,
80	    TNewParams,
81	    Overwrite<TNewParams, $Params>
82	  >;
83	
84	  /**
85	   * List of middlewares within this middleware builder
86	   */
87	  _middlewares: MiddlewareFunction<TRoot, TNewParams>[];
88	}
89	
90	/**
91	 * @internal
92	 * FIXME: there must be a nicer way of doing this, it's hard to maintain when we have several structures like this
93	 */
94	type CreateMiddlewareReturnInput<
95	  TRoot extends ProcedureParams,
96	  TPrev extends ProcedureParams,
97	  TNext extends ProcedureParams,
98	> = MiddlewareBuilder<
99	  TRoot,
100	  {
101	    _config: TPrev['_config'];
102	    _meta: TPrev['_meta'];
103	    _ctx_out: Overwrite<TPrev['_ctx_out'], TNext['_ctx_out']>;
104	    _input_in: FallbackValue<TNext['_input_in'], TPrev['_input_in']>;
105	    _input_out: FallbackValue<TNext['_input_out'], TPrev['_input_out']>;
106	    _output_in: FallbackValue<TNext['_output_in'], TPrev['_output_in']>;
107	    _output_out: FallbackValue<TNext['_output_out'], TPrev['_output_out']>;
108	  }
109	>;
110	
111	/**
112	 * @internal
113	 */
114	type deriveParamsFromConfig<
115	  TConfig extends AnyRootConfig,
116	  TInputIn = unknown,
117	> = {
118	  _config: TConfig;
119	  // eslint-disable-next-line @typescript-eslint/ban-types
120	  _ctx_out: {};
121	  _input_out: TInputIn;
122	  _input_in: TInputIn;
123	  _output_in: unknown;
124	  _output_out: unknown;
125	  _meta: TConfig['$types']['meta'];
126	};
127	/**
128	 * @internal
129	 */
130	export type MiddlewareFunction<
131	  TParams extends ProcedureParams,
132	  TParamsAfter extends ProcedureParams,
133	> = {
134	  (opts: {
135	    ctx: Simplify<
136	      Overwrite<TParams['_config']['$types']['ctx'], TParams['_ctx_out']>
137	    >;
138	    type: ProcedureType;
139	    path: string;
140	    input: TParams['_input_out'];
141	    rawInput: unknown;
142	    meta: TParams['_meta'] | undefined;
143	    next: {
144	      (): Promise<MiddlewareResult<TParams>>;
145	      <$Context>(opts: { ctx: $Context }): Promise<
146	        MiddlewareResult<{
147	          _config: TParams['_config'];
148	          _ctx_out: $Context;
149	          _input_in: TParams['_input_in'];
150	          _input_out: TParams['_input_out'];
151	          _output_in: TParams['_output_in'];
152	          _output_out: TParams['_output_out'];
153	          _meta: TParams['_meta'];
154	        }>
155	      >;
156	      (opts: { rawInput: unknown }): Promise<MiddlewareResult<TParams>>;
157	    };
158	  }): Promise<MiddlewareResult<TParamsAfter>>;
159	  _type?: string | undefined;
160	};
161	
162	/**
163	 * @internal
164	 */
165	export function createMiddlewareFactory<
166	  TConfig extends AnyRootConfig,
167	  TInputIn = unknown,
168	>() {
169	  function createMiddlewareInner<TNewParams extends ProcedureParams>(
170	    middlewares: MiddlewareFunction<any, any>[],
171	  ): MiddlewareBuilder<deriveParamsFromConfig<TConfig, TInputIn>, TNewParams> {
172	    return {
173	      _middlewares: middlewares,
174	      unstable_pipe(middlewareBuilderOrFn) {
175	        const pipedMiddleware =
176	          '_middlewares' in middlewareBuilderOrFn
177	            ? middlewareBuilderOrFn._middlewares
178	            : [middlewareBuilderOrFn];
179	
180	        return createMiddlewareInner([
181	          ...(middlewares as any),
182	          ...pipedMiddleware,
183	        ]);
184	      },
185	    };
186	  }
187	
188	  function createMiddleware<TNewParams extends ProcedureParams>(
189	    fn: MiddlewareFunction<
190	      deriveParamsFromConfig<TConfig, TInputIn>,
191	      TNewParams
192	    >,
193	  ): MiddlewareBuilder<deriveParamsFromConfig<TConfig, TInputIn>, TNewParams> {
194	    return createMiddlewareInner([fn]);
195	  }
196	
197	  return createMiddleware;
198	}
199	
200	export const experimental_standaloneMiddleware = <
201	  TCtx extends {
202	    ctx?: object;
203	    meta?: object;
204	    input?: unknown;
205	  },
206	>() => ({
207	  create: createMiddlewareFactory<
208	    RootConfig<{
209	      ctx: TCtx extends { ctx: infer T extends object } ? T : object;
210	      meta: TCtx extends { meta: infer T extends object } ? T : object;
211	      errorShape: object;
212	      transformer: object;
213	    }>,
214	    TCtx extends { input: infer T } ? T : unknown
215	  >(),
216	});
217	
218	function isPlainObject(obj: unknown) {
219	  return obj && typeof obj === 'object' && !Array.isArray(obj);
220	}
221	
222	/**
223	 * @internal
224	 * Please note, `trpc-openapi` uses this function.
225	 */
226	export function createInputMiddleware<TInput>(parse: ParseFn<TInput>) {
227	  const inputMiddleware: ProcedureBuilderMiddleware = async ({
228	    next,
229	    rawInput,
230	    input,
231	  }) => {
232	    let parsedInput: ReturnType<typeof parse>;
233	    try {
234	      parsedInput = await parse(rawInput);
235	    } catch (cause) {
236	      throw new TRPCError({
237	        code: 'BAD_REQUEST',
238	        cause,
239	      });
240	    }
241	
242	    // Multiple input parsers
243	    const combinedInput =
244	      isPlainObject(input) && isPlainObject(parsedInput)
245	        ? {
246	            ...input,
247	            ...parsedInput,
248	          }
249	        : parsedInput;
250	
251	    // TODO fix this typing?
252	    return next({ input: combinedInput } as any);
253	  };
254	  inputMiddleware._type = 'input';
255	  return inputMiddleware;
256	}
257	
258	/**
259	 * @internal
260	 */
261	export function createOutputMiddleware<TOutput>(parse: ParseFn<TOutput>) {
262	  const outputMiddleware: ProcedureBuilderMiddleware = async ({ next }) => {
263	    const result = await next();
264	    if (!result.ok) {
265	      // pass through failures without validating
266	      return result;
267	    }
268	    try {
269	      const data = await parse(result.data);
270	      return {
271	        ...result,
272	        data,
273	      };
274	    } catch (cause) {
275	      throw new TRPCError({
276	        message: 'Output validation failed',
277	        code: 'INTERNAL_SERVER_ERROR',
278	        cause,
279	      });
280	    }
281	  };
282	  outputMiddleware._type = 'output';
283	  return outputMiddleware;
284	}
