374	                  : callOpts.ctx,
375	              input:
376	                nextOpts && 'input' in nextOpts
377	                  ? nextOpts.input
378	                  : callOpts.input,
379	              rawInput:
380	                nextOpts && 'rawInput' in nextOpts
381	                  ? nextOpts.rawInput
382	                  : callOpts.rawInput,
383	            });
384	          },
385	        });
