404	      });
405	    }
406	    if (!result.ok) {
407	      // re-throw original error
408	      throw result.error;
409	    }
410	    return result.data;
411	  };
412	  procedure._def = _def;
413	  procedure.meta = _def.meta;
414	
415	  return procedure as AnyProcedure;
